/-- The assertion that `f` and `g` are conditionally independent relative to `h`. -/
def CondIndepFun (f : Ω → α) (g : Ω → β) (h : Ω → γ) (μ : Measure Ω := by volume_tac) : Prop :=
  ∀ᵐ z ∂ (μ.map h), IndepFun f g (μ[|h ← z])

def IsBayesEstimator (E : estimationProblem Θ 𝒴 𝒵) (P : Kernel Θ 𝒳)
    (κ : Kernel 𝒳 𝒵) (π : Measure Θ) : Prop :=
  bayesianRisk E P κ π = bayesRiskPrior E P π

def bayesianRisk (E : estimationProblem Θ 𝒴 𝒵) (P : Kernel Θ 𝒳)
    (κ : Kernel 𝒳 𝒵) (π : Measure Θ) : ℝ≥0∞ :=
  ∫⁻ θ, risk E P κ θ ∂π

def condFDiv (f : ℝ → ℝ) (κ η : Kernel α β) (μ : Measure α) : EReal :=
  if (∀ᵐ a ∂μ, fDiv f (κ a) (η a) ≠ ⊤)
    ∧ (Integrable (fun x ↦ (fDiv f (κ x) (η x)).toReal) μ)
  then ((μ[fun x ↦ (fDiv f (κ x) (η x)).toReal] : ℝ) : EReal)
  else ⊤

def condKL (κ η : Kernel α β) (μ : Measure α) : EReal :=
  if (∀ᵐ a ∂μ, kl (κ a) (η a) ≠ ⊤)
    ∧ (Integrable (fun a ↦ (kl (κ a) (η a)).toReal) μ)
  then ((μ[fun a ↦ (kl (κ a) (η a)).toReal] : ℝ) : EReal)
  else ⊤

def fDiv (f : ℝ → ℝ) (μ ν : Measure α) : EReal :=
  if ¬ Integrable (fun x ↦ f ((∂μ/∂ν) x).toReal) ν then ⊤
  else ∫ x, f ((∂μ/∂ν) x).toReal ∂ν + derivAtTop f * μ.singularPart ν .univ

noncomputable def renyiDiv (a : ℝ) (μ ν : Measure α) : EReal :=
  if a = 1 then kl μ ν
  else (a - 1)⁻¹ * ENNReal.log ((↑(ν .univ) + (a - 1) * (hellingerDiv a μ ν)).toENNReal)

def bayesRiskIncrease (E : estimationProblem Θ 𝒴 𝒵) (P : Kernel Θ 𝒳) (π : Measure Θ)
    (η : Kernel 𝒳 𝒳') : ℝ≥0∞ :=
  bayesRiskPrior E (η ∘ₖ P) π - bayesRiskPrior E P π

